import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 11 How to grow old","description":"学习 动名词短语作主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 11 How to grow old","description":"学习 动名词短语作主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 动名词短语作主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 10 Silicon Valley","link":"/life/english/new-concept/book-4/unit-02/lesson-010"},"next":{"text":"第四册：流利英语 · Lesson 12 Banks and their customers","link":"/life/english/new-concept/book-4/unit-02/lesson-012"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 10 Silicon Valley","link":"/life/english/new-concept/book-4/unit-02/lesson-010"},"next":{"text":"第四册：流利英语 · Lesson 12 Banks and their customers","link":"/life/english/new-concept/book-4/unit-02/lesson-012"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-011.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-011.md"}'),i={name:"life/english/new-concept/book-4/unit-02/lesson-011.md"};function l(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-11-how-to-grow-old" tabindex="-1">第四册：流利英语 · Lesson 11 How to grow old <a class="header-anchor" href="#第四册-流利英语-·-lesson-11-how-to-grow-old" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 11 How to grow old&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕年龄、兴趣与生活态度阅读议论性文字，区分个人建议和对所有人的普遍命令。训练把抽象忠告改写为带条件、可执行的小行动，并尊重不同健康状态与生活条件。重点掌握动名词作主语，避免在复杂主语后误用复数谓语。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>ageing</td><td>/ˈeɪdʒɪŋ/</td><td>n.</td><td>变老过程</td><td>attitudes to ageing</td></tr><tr><td>curiosity</td><td>/ˌkjʊəriˈɒsəti/</td><td>n.</td><td>好奇心</td><td>maintain curiosity</td></tr><tr><td>routine</td><td>/ruːˈtiːn/</td><td>n.</td><td>日常习惯</td><td>a flexible routine</td></tr><tr><td>interest</td><td>/ˈɪntrəst/</td><td>n.</td><td>兴趣</td><td>develop an interest</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take an interest in — 对某事产生兴趣</li><li>keep in touch with — 与某人保持联系</li></ul><h2 id="语法讲解-动名词短语作主语" tabindex="-1">语法讲解：动名词短语作主语 <a class="header-anchor" href="#语法讲解-动名词短语作主语" aria-label="Permalink to &quot;语法讲解：动名词短语作主语&quot;">​</a></h2><p>Keeping a journal 是一个活动概念，作主语时通常接单数谓语，即使短语内部带有复数宾语也不改变一致关系。两个不同活动由 and 连接时通常用复数谓语；如果构成一个整体概念则要结合语境判断。动名词主语强调活动本身，不等于现在进行时。主语较长时可以使用 It is useful to… 改写，但语气和信息重心会略有变化。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Learning the names of local plants gives Mei a reason to walk outdoors.</p></blockquote><p>认识当地植物的名称让梅有了去户外散步的理由。</p><p>Learning…plants 是完整动名词主语，中心是活动，因此谓语用 gives，而不是受 names 影响用 give。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Learning new skills are rewarding 中 are 应改 is；skills 只是动名词的宾语。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先把长主语作为一个意群朗读，再读 gives 或 is；检查不要在 names 后错误停顿。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Keeping a small sketchbook can make daily walks more interesting. Start with one familiar tree. If walking is difficult, sketching from a window is another option.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为愿意尝试新爱好的退休邻居提出三句温和建议，含一个动名词主语和一个条件。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>can 与 if 留出个体差异，末句使建议适用于不同条件。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：Keeping old photographs ___ enjoyable for him.（be）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 整个动名词短语作为一个活动，接单数谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中的主语到哪个词结束？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> plants</p><p><strong>解析：</strong> Learning the names of local plants 为完整主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 It is useful to record small observations. 改为动名词主语句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Recording small observations is useful.</p><p><strong>解析：</strong> recording 短语替代形式主语结构中的活动。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词短语作主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-010">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-012">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
